# Hand-written FastAPI router (never generated by gherkin-ai).
from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel, EmailStr, Field

from app import services
from app.auth import get_current_user, require_role

router = APIRouter(prefix="/orders", tags=["orders"])


class PlaceOrderRequest(BaseModel):
    customer_email: EmailStr
    items: list[str] = Field(..., min_length=1)
    quantity: int = Field(gt=0)


@router.post("", status_code=status.HTTP_201_CREATED)
def place_order(request: PlaceOrderRequest, user=Depends(get_current_user)):
    return services.place_order(request)


@router.post("/{order_id}/cancel")
def cancel_order(order_id: str, user=Depends(require_role("manager"))):
    order = services.find_order(order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="Order not found")
    return services.cancel_order(order)


@router.get("/{order_id}")
def get_order(order_id: str):
    order = services.find_order(order_id)
    if not order:
        raise HTTPException(status.HTTP_404_NOT_FOUND, "Order not found")
    return order
